Func<dynamic, Context, CancellationToken, Task> HandleAsync = async (view, ctx, ct) =>
{

    if (view.Host is not Orc.Cards.Card self || view.Card is not Orc.Cards.Card played) { return; }
    if (!object.ReferenceEquals(played, self)) { return; }

    var runtime = Orc.Game.Effects.EffectRuntime.ResolveFor(self);
    var service = Orc.Game.MatchCardService.ResolveFor(self);
    var engine = ctx.Engine;
    if (runtime is null || service is null || engine is null) { return; }

    Func<Orc.Cards.Card, Orc.Game.Players.Player?> ownerOf = c =>
    {
        if (c is Orc.Game.Players.Hq hq) { return hq.Owner; }
        if (c is Orc.Game.Cards.CardBase cb) { return cb.Owner; }
        return null;
    };

    Func<Orc.Game.Cards.UnitCard, bool> onField = u =>
        u.TryGetData<Orc.Game.Cards.UnitStateData>(out var st) && !st.IsDestroyed && st.Line is not null;

    Func<Orc.Game.Cards.UnitCard, bool> isInfantry = u =>
    {
        foreach (var t in u.Definition.UnitTypes)
        {
            if (string.Equals(t, "infantry", System.StringComparison.OrdinalIgnoreCase)) { return true; }
        }
        return false;
    };

    Func<Orc.Game.Cards.UnitCard, bool> onFrontLine = u =>
    {
        if (!u.TryGetData<Orc.Game.Cards.UnitStateData>(out var st) || st.IsDestroyed || st.Line is null)
        {
            return false;
        }
        return st.Line.Name.Contains("前线", System.StringComparison.Ordinal);
    };

    var owner = ownerOf(self);
    if (owner is null) { return; }

    // 前置：前线有友方单位。
    var hasFriendlyFront = false;
    foreach (var c in engine.Cards)
    {
        if (c is Orc.Game.Cards.UnitCard u && object.ReferenceEquals(u.Owner, owner) && onFrontLine(u))
        {
            hasFriendlyFront = true;
            break;
        }
    }

    if (!hasFriendlyFront) { return; }

    var handUnits = new System.Collections.Generic.List<Orc.Game.Cards.UnitCard>();
    foreach (var c in owner.Hand)
    {
        if (c is Orc.Game.Cards.UnitCard uc && uc.Definition.DeployCost <= 2) { handUnits.Add(uc); }
    }

    foreach (var uc in handUnits)
    {
        var slots = service.GetAdjacentEmptySlots(owner);
        if (slots.Count == 0) { break; }

        owner.Hand.Remove(uc);
        await service.PlaceToSupportLineAsync(uc, owner, slots[0], ct);
        if (!onField(uc)) { continue; }

        await runtime.MoveAsync(uc, "frontline", ct);
        await runtime.PinAsync(uc, ct, self);
    }
};
